<?php
// Executed test suite. Usage:  AUVRYON_DB=auvryon_test php tests/run_tests.php
// Resets the target database (schema + base data), so NEVER point it at a database you want to keep.
require __DIR__ . '/../lib/boot.php';
$dbname = cfg('db')['name']; if ($dbname === 'auvryon_db' && getenv('ALLOW_PROD') !== '1') { fwrite(STDERR, "Refusing to run against auvryon_db. Set AUVRYON_DB=auvryon_test.\n"); exit(2); }
$results = []; $failed = 0;
function tc(string $name, callable $fn) { global $results, $failed; try { $fn(); $results[] = ['PASS', $name, '']; } catch (Throwable $e) { $failed++; $results[] = ['FAIL', $name, $e->getMessage() . ' @' . basename($e->getFile()) . ':' . $e->getLine()]; } }
function ok($c, string $m = 'assertion failed') { if (!$c) throw new Exception($m); }
function eq($a, $b, string $m = '') { if ((string)$a !== (string)$b) throw new Exception("$m expected [$b] got [$a]"); }
function raises(callable $fn, string $needle = '') { try { $fn(); } catch (AppError $e) { if ($needle !== '' && stripos($e->getMessage(), $needle) === false) throw new Exception("wrong error: " . $e->getMessage()); return $e; } throw new Exception('expected an AppError' . ($needle ? " containing '$needle'" : '')); }
$N = 0;
function em(int $u): string { return (string)val('SELECT email FROM users WHERE id=?', [$u]); }
function mk(string $name, string $bdt = '0', string $role = 'user'): int { global $N; $N++; q("DELETE FROM rate_limits WHERE bucket LIKE 'register:%'"); $u = Auth::register(['name' => $name, 'email' => "t$N@test.local", 'password' => 'Test@1234', 'pin' => '1234', 'role' => $role, 'business' => "Biz $N"]); if ((float)$bdt > 0) Pay::topup($u, 'BDT', cents($bdt)); return $u; }
function bal(int $u, string $c = 'BDT'): string { return (string)Ledger::wallet($u, $c)['balance']; }
function send(int $f, int $t, string $a, ?string $key = null, bool $hold = false, array $x = []): array { return Pay::send($x + ['from_user' => $f, 'to_user' => $t, 'currency' => 'BDT', 'amount_c' => cents($a), 'type' => 'transfer', 'category' => 'transfer', 'note' => 't', 'idem_key' => $key ?? bin2hex(random_bytes(8)), 'actor' => $f, 'allow_hold' => $hold]); }
function inv(): void { foreach (Ledger::reconcile() as [$n, $okk, $d]) if (!$okk) throw new Exception("Invariant failed: $n - $d"); }
function par(string $action, array $argsList): array {
  $start = microtime(true) + 1.2; $procs = [];
  foreach ($argsList as $a) { $p = proc_open([PHP_BINARY, __DIR__ . '/worker.php', $action, json_encode($a), (string)$start], [1 => ['pipe', 'w'], 2 => ['pipe', 'w']], $pipes, null, ['AUVRYON_DB' => cfg('db')['name'], 'PATH' => getenv('PATH')]); $procs[] = [$p, $pipes]; }
  $out = []; foreach ($procs as [$p, $pipes]) { $s = stream_get_contents($pipes[1]); $e = stream_get_contents($pipes[2]); proc_close($p); $j = json_decode($s, true); $out[] = $j ?: ['ok' => false, 'error' => "no json: $s $e"]; }
  return $out;
}
function succ(array $r): int { return count(array_filter($r, fn($x) => $x['ok'] && empty($x['duplicate']))); }

