// ===================== 4. Idempotency & concurrency =====================
tc('IDEM-01 repeating the same key never debits twice', function () use ($A, $B) { $k = 'idem-' . bin2hex(random_bytes(4)); $b0 = cents(bal($A)); $r1 = send($A, $B, '70', $k); $r2 = send($A, $B, '70', $k); $r3 = send($A, $B, '70', $k); eq($r1['txn_id'], $r2['txn_id']); ok(!empty($r2['duplicate']) && !empty($r3['duplicate'])); eq(cents(bal($A)), $b0 - 7000 - 100); });
tc('CONC-01 8 parallel requests with ONE idempotency key create exactly one transaction', function () use ($A, $B) { $k = 'par-' . bin2hex(random_bytes(4)); $b0 = cents(bal($A)); $n0 = (int)val('SELECT COUNT(*) FROM transactions'); $a = ['from_user' => $A, 'to_user' => $B, 'currency' => 'BDT', 'amount_c' => 8000, 'type' => 'transfer', 'category' => 'transfer', 'note' => 'par', 'idem_key' => $k, 'actor' => $A, 'allow_hold' => false]; $r = par('send', array_fill(0, 8, $a)); eq(succ($r), 1, 'fresh successes'); eq((int)val('SELECT COUNT(*) FROM transactions') - $n0, 1); eq(cents(bal($A)), $b0 - 8000 - 100); inv(); });
tc('CONC-02 parallel double-spend: 10 workers x 300 against a 1000 balance -> max 3 succeed, never negative', function () { $S = mk('Spender', '1000'); $R = mk('Receiver', '0'); Pay::topup($R, 'BDT', cents('1')); send($S, $R, '1', 'warm'); $args = []; for ($i = 0; $i < 10; $i++) $args[] = ['from_user' => $S, 'to_user' => $R, 'currency' => 'BDT', 'amount_c' => 30000, 'type' => 'settlement', 'fee_mode' => 'none', 'category' => 'x', 'note' => 'dbl', 'idem_key' => "ds$i", 'actor' => $S, 'allow_hold' => false]; $r = par('send', $args); $s = succ($r); $left = bal($S); ok($s === 3, "expected 3 successes, got $s"); ok(cents($left) >= 0); eq($left, '98.00', 'remaining'); inv(); });
tc('CONC-03 6 parallel cancels of one hold: exactly one wins, funds restored once', function () { $S = mk('S2', '2000'); $R = mk('R2', '0'); $r = send($S, $R, '600', null, true); $b0 = cents(bal($S)); $res = par('cancel', array_fill(0, 6, ['uid' => $S, 'txn' => $r['txn_id']])); eq(succ($res), 1, 'cancel winners'); eq(cents(bal($S)), $b0 + 60000 + 300); eq(bal($R), '0.00'); inv(); });
tc('CONC-04 cancel racing the release job: never both', function () { $S = mk('S3', '2000'); $R = mk('R3', '0'); $r = send($S, $R, '600', null, true); q("UPDATE transfer_holds SET release_at=DATE_ADD(NOW(), INTERVAL 2 SECOND) WHERE txn_id=?", [$r['txn_id']]); $start = microtime(true); $a = par('cancel', [['uid' => $S, 'txn' => $r['txn_id']], ['uid' => $S, 'txn' => $r['txn_id']]]); sleep(1); Pay::processHolds(); $st = val('SELECT status FROM transactions WHERE id=?', [$r['txn_id']]); ok(in_array($st, ['cancelled', 'completed'], true)); if ($st === 'cancelled') eq(bal($R), '0.00'); else eq(bal($R), '600.00'); inv(); });
tc('CONC-05 two parallel release jobs release a hold once', function () { $S = mk('S4', '2000'); $R = mk('R4', '0'); $r = send($S, $R, '600', null, true); q("UPDATE transfer_holds SET release_at=DATE_SUB(NOW(), INTERVAL 1 SECOND) WHERE txn_id=?", [$r['txn_id']]); par('process', [[], []]); eq(bal($R), '600.00'); inv(); });
