tc('GRP-08 optimisation: exact DP matches brute-force minimum on 300 random zero-sum cases', function () {
  mt_srand(7);
  for ($i = 0; $i < 300; $i++) { $n = mt_rand(2, 8); $v = []; for ($j = 0; $j < $n - 1; $j++) $v[] = mt_rand(-50, 50) * 100; $v[] = -array_sum($v); $net = []; foreach ($v as $j => $x) $net[$j + 1] = $x;
    $res = Groups::optimize($net); $chk = $net; foreach ($res['transfers'] as $tr) { $chk[$tr['from']] += $tr['amount_c']; $chk[$tr['to']] -= $tr['amount_c']; } ok(array_sum(array_map('abs', $chk)) === 0, 'transfers do not clear balances');
    $nz = array_values(array_filter($v)); $m = count($nz);
    $memo = []; $f = function (int $mask) use (&$f, &$memo, $nz, $m) { if ($mask === 0) return 0; if (isset($memo[$mask])) return $memo[$mask]; $low = $mask & -$mask; $best = -999; for ($sub = $mask; $sub > 0; $sub = ($sub - 1) & $mask) { if (!($sub & $low)) continue; $s = 0; for ($b = 0; $b < $m; $b++) if ($sub & (1 << $b)) $s += $nz[$b]; if ($s === 0) { $r = $f($mask ^ $sub); if ($r >= 0) $best = max($best, 1 + $r); } } return $memo[$mask] = $best; };
    $k = $m ? $f((1 << $m) - 1) : 0; eq(count($res['transfers']), $m - $k, "case $i minimal transfers"); } });
tc('GRP-09 greedy fallback (13+ members) still clears every balance within n-1 transfers', function () { $net = []; $s = 0; for ($i = 1; $i <= 14; $i++) { $x = $i <= 13 ? mt_rand(-40, 40) * 100 : -$s; $s += ($i <= 13 ? $x : 0); $net[$i] = $x; } $res = Groups::optimize($net); ok(strpos($res['method'], 'greedy') === 0); ok(count($res['transfers']) <= 13); $c = $net; foreach ($res['transfers'] as $t) { $c[$t['from']] += $t['amount_c']; $c[$t['to']] -= $t['amount_c']; } eq(array_sum(array_map('abs', $c)), 0); });
tc('GRP-10 shared group budget tracks the group spend', function () use ($gid, $G1) { q('INSERT INTO budgets (user_id,group_id,category,monthly_limit) VALUES (?,?,?,?)', [$G1, $gid, 'general', '1000']); $b = array_values(array_filter(Cash::budgetStatus($G1), fn($x) => $x['group_id'] > 0))[0]; eq($b['spent'], '900.00'); });
