// ===================== 10. Escrow =====================
$EB = mk('EscBuyer', '10000'); $ES = mk('EscSeller', '0'); $eid = Escrow::create($EB, "t{$N}@test.local", 'Job', 'BDT', [['title' => 'M1', 'amount' => '1000'], ['title' => 'M2', 'amount' => '2000'], ['title' => 'M3', 'amount' => '500']]); $ms = array_column(rows('SELECT id FROM escrow_milestones WHERE escrow_id=? ORDER BY seq', [$eid]), 'id');
tc('ESC-01 funding moves money into the separate escrow account', function () use ($EB, $ms) { Escrow::fund($EB, (int)$ms[0], 'e1'); eq(bal($EB), '9000.00'); ok(cents(val("SELECT balance FROM ledger_accounts WHERE code='SYS-ESCROW-BDT'")) >= 100000); inv(); });
tc('ESC-02 only the buyer funds; funding twice refused', function () use ($ES, $EB, $ms) { raises(fn() => Escrow::fund($ES, (int)$ms[1], 'e2'), 'buyer'); raises(fn() => Escrow::fund($EB, (int)$ms[0], 'e3'), 'already'); });
tc('ESC-03 only buyer releases; seller gets amount minus fee', function () use ($ES, $EB, $ms) { raises(fn() => Escrow::close($ES, (int)$ms[0], 'release'), 'buyer'); Escrow::submit($ES, (int)$ms[0]); Escrow::close($EB, (int)$ms[0], 'release'); eq(bal($ES), '990.00'); inv(); });
tc('ESC-04 released milestone cannot be released or refunded again', function () use ($EB, $ES, $ms) { raises(fn() => Escrow::close($EB, (int)$ms[0], 'release'), 'not held'); raises(fn() => Escrow::close($ES, (int)$ms[0], 'refund'), 'not held'); });
tc('ESC-05 8 parallel releases of one milestone: single payout', function () use ($EB, $ES, $ms) { Escrow::fund($EB, (int)$ms[1], 'e4'); $s0 = cents(bal($ES)); $r = par('release', array_fill(0, 8, ['uid' => $EB, 'ms' => (int)$ms[1], 'mode' => 'release'])); eq(succ($r), 1); eq(cents(bal($ES)), $s0 + 198000); inv(); });
tc('ESC-06 seller voluntary refund returns full amount to buyer', function () use ($EB, $ES, $ms) { Escrow::fund($EB, (int)$ms[2], 'e5'); $b = cents(bal($EB)); Escrow::close($ES, (int)$ms[2], 'refund'); eq(cents(bal($EB)), $b + 50000); eq(val('SELECT status FROM escrows WHERE id=?', [val('SELECT escrow_id FROM escrow_milestones WHERE id=?', [$ms[2]])]), 'completed'); inv(); });
$ADM = mk('Admin1', '0'); q("UPDATE users SET role_id=3 WHERE id=?", [$ADM]);
function newEsc(int $buyer, int $seller, string $amt): int { Escrow::create($buyer, em($seller), 'Job', 'BDT', [['title' => 'D', 'amount' => $amt]]); return (int)val('SELECT MAX(id) FROM escrow_milestones'); }
tc('ESC-07 dispute → admin refund returns held funds; dispute closed with timeline', function () use ($EB, $ES, $ADM) { $m = newEsc($EB, $ES, '700'); Escrow::fund($EB, $m, 'e6'); $d = Disputes::open($EB, null, $m, 'Not delivered at all'); raises(fn() => Escrow::close($EB, $m, 'release'), 'dispute'); Disputes::evidence($ES, $d, 'Delivered by email'); $b = cents(bal($EB)); Disputes::decide($ADM, $d, 'refund', 'No proof of delivery'); eq(cents(bal($EB)), $b + 70000); eq(val('SELECT status FROM disputes WHERE id=?', [$d]), 'resolved'); ok(val("SELECT COUNT(*) FROM timeline_events WHERE entity_type='dispute' AND entity_id=?", [$d]) >= 3); raises(fn() => Disputes::decide($ADM, $d, 'refund', 'again'), 'closed'); inv(); });
tc('ESC-08 dispute → admin release pays the seller minus fee', function () use ($EB, $ES, $ADM) { $m = newEsc($EB, $ES, '300'); Escrow::fund($EB, $m, 'e7'); $d = Disputes::open($ES, null, $m, 'Buyer is ignoring delivered work'); $s = cents(bal($ES)); Disputes::decide($ADM, $d, 'release', 'Delivery confirmed'); eq(cents(bal($ES)), $s + 29700); inv(); });
tc('ESC-09 non-participant cannot dispute or read evidence rights', function () use ($EB, $ES) { $m = newEsc($EB, $ES, '100'); Escrow::fund($EB, $m, 'e8'); $o = mk('Outsider', '0'); raises(fn() => Disputes::open($o, null, $m, 'I am not part of this'), 'not found'); });
// ===================== 11. Invoices =====================
$IM = mk('InvIssuer', '0', 'merchant'); $IP = mk('InvPayer', '3000'); $inv = Invoices::create($IM, ['title' => 'Work', 'customer_name' => 'Payer', 'due' => date('Y-m-d', strtotime('+7 days')), 'items' => [['description' => 'A', 'qty' => '2', 'price' => '500'], ['description' => 'B', 'qty' => '1', 'price' => '250']]]); $tok = (string)val('SELECT link_token FROM invoices WHERE id=?', [$inv]);
tc('INV-01 invoice total = sum of line items', fn() => eq(Invoices::totals($inv)['total_c'], 125000));
tc('INV-02 partial payment reconciles automatically (status partial, due reduced)', function () use ($inv, $tok, $IP) { Invoices::pay($IP, $tok, cents('400'), 'i1'); eq(val('SELECT status FROM invoices WHERE id=?', [$inv]), 'partial'); eq(Invoices::totals($inv)['due_c'], 85000); inv(); });
tc('INV-03 overpayment refused', function () use ($tok, $IP) { raises(fn() => Invoices::pay($IP, $tok, cents('900'), 'i2'), 'between'); });
tc('INV-04 same idempotency key does not double-pay', function () use ($inv, $tok, $IP) { Invoices::pay($IP, $tok, cents('100'), 'i3'); Invoices::pay($IP, $tok, cents('100'), 'i3'); eq(Invoices::totals($inv)['paid_c'], 50000); });
tc('INV-05 5 parallel payments of 300 vs 750 outstanding: total paid never exceeds invoice', function () use ($inv, $tok) { $us = []; for ($i = 0; $i < 5; $i++) $us[] = mk("IP$i", '1000'); $a = []; foreach ($us as $i => $u) $a[] = ['uid' => $u, 'token' => $tok, 'amount' => '300', 'idem' => "ip$i"]; $r = par('invoice', $a); $t = Invoices::totals($inv); eq(succ($r), 2, 'only two 300 payments fit in 750'); eq($t['paid_c'], 110000); ok($t['paid_c'] <= $t['total_c']); inv(); });
tc('INV-06 paying in full marks paid and blocks further payment', function () use ($inv, $tok, $IP) { $left = Invoices::totals($inv)['due_c']; if ($left > 0) Invoices::pay($IP, $tok, $left, 'i-final'); eq(val('SELECT status FROM invoices WHERE id=?', [$inv]), 'paid'); raises(fn() => Invoices::pay($IP, $tok, '1', 'i-x'), 'paid'); });
tc('INV-07 issuer cannot pay their own invoice', function () use ($IM) { $i2 = Invoices::create($IM, ['title' => 'T', 'customer_name' => 'C', 'due' => date('Y-m-d', strtotime('+7 days')), 'items' => [['description' => 'A', 'qty' => '1', 'price' => '100']]]); raises(fn() => Invoices::pay($IM, (string)val('SELECT link_token FROM invoices WHERE id=?', [$i2]), cents('10'), 'self'), 'own'); });
// ===================== 12. Rules =====================
$RU = mk('RuleUser', '2000'); $RT = mk('RuleTarget', '0'); $pk = Pockets::create($RU, 'Goal', 'travel', '5000', null);
tc('RULE-01 scheduled transfer runs once per scheduled date even if triggered twice', function () use ($RU, $RT) { Rules::create($RU, ['rule_type' => 'scheduled_transfer', 'target' => "t{$GLOBALS['N']}@test.local", 'amount' => '100', 'frequency' => 'weekly', 'next_run' => date('Y-m-d')]); $b = cents(bal($RT)); Rules::runDue(); Rules::runDue(); eq(cents(bal($RT)), $b + 10000); eq(val("SELECT COUNT(*) FROM rule_runs WHERE status='success' AND rule_id=(SELECT MAX(id) FROM money_rules)"), 1); });
tc('RULE-02 two parallel runners cannot double-execute a rule run', function () use ($RU, $RT) { Rules::create($RU, ['rule_type' => 'scheduled_transfer', 'target' => "t{$GLOBALS['N']}@test.local", 'amount' => '50', 'frequency' => 'daily', 'next_run' => date('Y-m-d')]); $rid = (int)val('SELECT MAX(id) FROM money_rules'); $b = cents(bal($RT)); par('rules', [[], []]); eq(cents(bal($RT)), $b + 5000, 'target gained once'); eq(val("SELECT COUNT(*) FROM rule_runs WHERE rule_id=? AND status='success'", [$rid]), 1); inv(); });
tc('RULE-03 failing rule is logged, retried, then marked failed after 3 failures', function () { $P = mk('Poor', '10'); $T = mk('PoorT', '0'); Rules::create($P, ['rule_type' => 'scheduled_transfer', 'target' => "t{$GLOBALS['N']}@test.local", 'amount' => '500', 'frequency' => 'daily', 'next_run' => date('Y-m-d')]); $rid = (int)val('SELECT MAX(id) FROM money_rules'); for ($i = 0; $i < 3; $i++) Rules::runDue(); eq(val('SELECT status FROM money_rules WHERE id=?', [$rid]), 'failed'); eq(val("SELECT COUNT(*) FROM rule_runs WHERE rule_id=? AND status='failed'", [$rid]), 3); eq(bal($T), '0.00'); });
tc('RULE-04 income allocation sends the percentage to the pocket exactly once per income event', function () { $I = mk('Inc', '0'); $p = Pockets::create($I, 'Save', 'emergency', '5000', null); Rules::create($I, ['rule_type' => 'income_allocation', 'pocket' => $p, 'percent' => 10]); $r = Pay::topup($I, 'BDT', cents('1000')); Rules::afterTxn($r['txn_id']); Rules::afterTxn($r['txn_id']); eq(val('SELECT balance FROM ledger_accounts WHERE id=(SELECT account_id FROM pockets WHERE id=?)', [$p]), '100.00'); eq(bal($I), '900.00'); inv(); });
tc('RULE-05 round-up moves the spare change to the pocket', function () use ($mid) { $I = mk('RU', '1000'); $p = Pockets::create($I, 'Spare', 'travel', '500', null); Rules::create($I, ['rule_type' => 'round_up', 'pocket' => $p, 'round_to' => 50]); $c = Pay::createCheckout($mid, '123', ''); Pay::payCheckout($I, $c['ref'], 'ru1'); eq(val('SELECT balance FROM ledger_accounts WHERE id=(SELECT account_id FROM pockets WHERE id=?)', [$p]), '27.00'); eq(bal($I), '850.00'); inv(); });
tc('RULE-06 low-balance alert fires once per day', function () use ($mid) { $I = mk('Low', '300'); Rules::create($I, ['rule_type' => 'low_balance_alert', 'threshold' => '500']); foreach ([1, 2] as $i) { $c = Pay::createCheckout($mid, '20', ''); Pay::payCheckout($I, $c['ref'], "low$i"); } eq(val("SELECT COUNT(*) FROM notifications WHERE user_id=? AND title='Low balance'", [$I]), 1); });
