$TU = mk('TokUser', '3000'); $tokPlain = Tokens::create($TU, $mid, '500', '800'); $tid = (int)val('SELECT id FROM virtual_tokens WHERE user_id=?', [$TU]);
tc('TOK-01 token is stored hashed, never plaintext', fn() => ok(!val('SELECT 1 FROM virtual_tokens WHERE token_hash=?', [$tokPlain]) && (bool)val('SELECT 1 FROM virtual_tokens WHERE token_hash=?', [hash('sha256', $tokPlain)])));
tc('TOK-02 merchant charge within limits is approved and posted', function () use ($tokPlain, $M, $TU) { $r = Tokens::charge($M, $tokPlain, cents('300'), 'tc1'); eq($r['status'], 'approved'); eq(bal($TU), '2700.00'); inv(); });
tc('TOK-03 per-charge and monthly limits decline (ghost-charge protection) and raise an alert', function () use ($tokPlain, $M, $TU) { eq(Tokens::charge($M, $tokPlain, cents('600'), 'tc2')['status'], 'declined'); Tokens::charge($M, $tokPlain, cents('400'), 'tc3'); eq(Tokens::charge($M, $tokPlain, cents('200'), 'tc4')['status'], 'declined'); ok(val("SELECT COUNT(*) FROM risk_alerts WHERE user_id=? AND alert_type='ghost_charge_blocked'", [$TU]) >= 2); });
tc('TOK-04 paused token declines; resumed token works; cancelled token declines forever', function () use ($tokPlain, $M, $TU, $tid) { $t2 = Tokens::create($TU, (int)val('SELECT id FROM merchants WHERE user_id=?', [$M]), '500', '5000'); $id2 = (int)val('SELECT MAX(id) FROM virtual_tokens'); Tokens::setStatus($TU, $id2, 'paused'); eq(Tokens::charge($M, $t2, cents('10'), 'tp1')['status'], 'declined'); Tokens::setStatus($TU, $id2, 'active'); eq(Tokens::charge($M, $t2, cents('10'), 'tp2')['status'], 'approved'); Tokens::setStatus($TU, $id2, 'cancelled'); eq(Tokens::charge($M, $t2, cents('10'), 'tp3')['status'], 'declined'); raises(fn() => Tokens::setStatus($TU, $id2, 'active'), 'cannot'); });
tc('TOK-05 another merchant cannot use the token', function () use ($tokPlain) { $M2 = mk('Shop2', '0', 'merchant'); raises(fn() => Tokens::charge($M2, $tokPlain, cents('10'), 'tx1'), 'different merchant'); });
