$OP = mk('OffPayer', '1000'); $OM = mk('OffShop', '0', 'merchant');
tc('OFF-01 issue → queue shows NOT settled; balance unchanged until sync', function () use ($OP, $OM) { $o = Offline::issue($OP, em($OM), '200'); Offline::queue($OM, $o['token']); eq(bal($OP), '1000.00'); eq(val("SELECT status FROM offline_queue WHERE merchant_user_id=?", [$OM]), 'queued'); ok(strpos((string)val('SELECT message FROM offline_queue WHERE merchant_user_id=?', [$OM]), 'NOT settled') !== false); $GLOBALS['tok1'] = $o['token']; });
tc('OFF-02 sync settles once with fee, and balance validation applies', function () use ($OP, $OM) { $r = Offline::sync($OM); eq($r['settled'], 1); eq(bal($OP), '800.00'); eq(bal($OM), '198.00'); inv(); });
tc('OFF-03 replaying the same token is refused and flagged', function () use ($OM, $OP) { Offline::queue($OM, $GLOBALS['tok1']); $r = Offline::sync($OM); eq($r['rejected'], 1); eq(bal($OP), '800.00'); ok(val("SELECT COUNT(*) FROM risk_alerts WHERE user_id=? AND alert_type='offline_replay'", [$OP]) >= 1); });
tc('OFF-04 tampered token is rejected at queue time', function () use ($OM) { $t = $GLOBALS['tok1']; $bad = substr($t, 0, -3) . 'AAA'; raises(fn() => Offline::queue($OM, $bad), 'valid'); raises(fn() => Offline::queue($OM, 'garbage'), 'valid'); });
tc('OFF-05 token issued for one merchant cannot be queued by another', function () use ($OP, $OM) { $o = Offline::issue($OP, em($OM), '10'); $O2 = mk('OffShop2', '0', 'merchant'); raises(fn() => Offline::queue($O2, $o['token']), 'different payee'); });
tc('OFF-06 expired token refused at sync', function () use ($OP, $OM) { $o = Offline::issue($OP, em($OM), '50'); q("UPDATE offline_tokens SET expires_at=DATE_SUB(NOW(), INTERVAL 1 HOUR) WHERE token_id=?", [Offline::decode($o['token'])['t']]); Offline::queue($OM, $o['token']); $r = Offline::sync($OM); eq($r['rejected'], 1); eq(bal($OP), '800.00'); });
tc('OFF-07 conflict: payer spent the money before sync → rejected, nothing charged', function () use ($OP, $OM) { $o = Offline::issue($OP, em($OM), '700'); $d = mk('Drain', '0'); send($OP, $d, '790', null, false, ['fee_mode' => 'none', 'type' => 'settlement']); Offline::queue($OM, $o['token']); $r = Offline::sync($OM); eq($r['rejected'], 1); ok(cents(bal($OP)) >= 0); eq(val("SELECT status FROM offline_tokens WHERE token_id=?", [Offline::decode($o['token'])['t']]), 'rejected'); inv(); });
tc('OFF-08 cannot issue more outstanding tokens than the balance', function () { $P = mk('OP2', '300'); mk('OS2', '0', 'merchant'); $e = "t{$GLOBALS['N']}@test.local"; Offline::issue($P, $e, '200'); raises(fn() => Offline::issue($P, $e, '200'), 'exceed'); });
tc('OFF-09 parallel syncs of the same queue settle each token once', function () { $P = mk('OP3', '1000'); $S = mk('OS3', '0', 'merchant'); $e = "t{$GLOBALS['N']}@test.local"; $o = Offline::issue($P, $e, '100'); Offline::queue($S, $o['token']); par('offline', [['uid' => $S], ['uid' => $S], ['uid' => $S]]); eq(bal($P), '900.00'); eq(bal($S), '99.00'); inv(); });
