q('INSERT INTO approval_policies (wallet_id,min_amount,required_approvals,created_by) VALUES (?,?,?,?)', [$apw['id'], '1000', 2, $AA]); $pol = (int)db()->lastInsertId(); foreach ([$AA, $AB] as $x) q('INSERT INTO approval_policy_approvers VALUES (?,?)', [$pol, $x]);
tc('APP-01 payment above the threshold is NOT executed; creates an approval request', function () use ($AP, $AR) { $b = bal($AP); $r = send($AP, $AR, '1500'); eq($r['status'], 'approval_pending'); eq(bal($AP), $b); eq(bal($AR), '0.00'); });
