tc('APP-04 same approver cannot vote twice; second approver executes the payment once', function () use ($AA, $AB, $AR) { $rid = (int)val('SELECT MAX(id) FROM approval_requests'); raises(fn() => Approvals::vote($AA, $rid, 'approve'), 'already voted'); eq(Approvals::vote($AB, $rid, 'approve'), 'executed'); eq(bal($AR), '2499.00'); raises(fn() => Approvals::vote($AB, $rid, 'approve'), 'no longer pending'); inv(); });
tc('APP-05 a rejection stops the payment and closes the request', function () use ($AP, $AR, $AA, $AB) { $b = bal($AP); send($AP, $AR, '1100'); $rid = (int)val('SELECT MAX(id) FROM approval_requests'); eq(Approvals::vote($AA, $rid, 'reject'), 'rejected'); eq(bal($AP), $b); raises(fn() => Approvals::vote($AB, $rid, 'approve'), 'no longer pending'); });
