// ===================== 17. Refund & dispute on a transaction =====================
tc('REF-01 refund reverses a transfer incl. fee; second refund impossible (service + DB unique)', function () { $S = mk('RS', '1000'); $R = mk('RR', '0'); $r = send($S, $R, '200'); $Ad = (int)val('SELECT id FROM users WHERE role_id=3 LIMIT 1'); $f0 = cents(val("SELECT balance FROM ledger_accounts WHERE code='SYS-FEE-BDT'")); Pay::refund($Ad, $r['txn_id'], 'test'); eq(bal($S), '1000.00'); eq(bal($R), '0.00'); eq(cents(val("SELECT balance FROM ledger_accounts WHERE code='SYS-FEE-BDT'")), $f0 - 100); raises(fn() => Pay::refund($Ad, $r['txn_id'], 'again'), 'already'); try { q("INSERT INTO transactions (ref,type,status,amount,currency,created_by,refund_of) VALUES ('DUPREFUND0001','refund','completed',1,'BDT',?,?)", [$Ad, $r['txn_id']]); throw new Exception('DB allowed duplicate refund'); } catch (PDOException $e) { ok($e->getCode() === '23000'); } inv(); });
tc('REF-02 8 parallel refunds of one transaction: exactly one succeeds', function () { $S = mk('RS2', '1000'); $R = mk('RR2', '0'); $r = send($S, $R, '200'); $Ad = (int)val('SELECT id FROM users WHERE role_id=3 LIMIT 1'); $res = par('refund', array_fill(0, 8, ['uid' => $Ad, 'txn' => $r['txn_id']])); eq(succ($res), 1); eq(bal($S), '1000.00'); inv(); });
tc('REF-03 refund fails atomically if the recipient already spent the money', function () { $S = mk('RS3', '1000'); $R = mk('RR3', '0'); $X = mk('RX3', '0'); $r = send($S, $R, '200'); send($R, $X, '195'); $Ad = (int)val('SELECT id FROM users WHERE role_id=3 LIMIT 1'); $b = bal($S); raises(fn() => Pay::refund($Ad, $r['txn_id'], 'x'), 'Insufficient'); eq(bal($S), $b); eq(val('SELECT status FROM transactions WHERE id=?', [$r['txn_id']]), 'completed'); inv(); });
tc('DSP-01 transaction dispute: only participants open; duplicates blocked; admin refund resolves', function () { $S = mk('DS', '1000'); $R = mk('DR', '0'); $O = mk('DO', '0'); $r = send($S, $R, '100'); raises(fn() => Disputes::open($O, $r['txn_id'], null, 'not mine at all'), 'not found'); $d = Disputes::open($S, $r['txn_id'], null, 'Sent by mistake to wrong person'); raises(fn() => Disputes::open($S, $r['txn_id'], null, 'again again again'), 'already open'); $Ad = (int)val('SELECT id FROM users WHERE role_id=3 LIMIT 1'); Disputes::decide($Ad, $d, 'refund', 'ok'); eq(bal($S), '1000.00'); eq(val('SELECT status FROM transactions WHERE id=?', [$r['txn_id']]), 'refunded'); inv(); });
// ===================== 18. Safe-to-spend & forecast =====================
tc('CASH-01 safe-to-spend arithmetic: balance - bills - savings plan - buffer (income excluded from conservative figure)', function () { $U = mk('Cash', '10000'); q("INSERT INTO recurring_items (user_id,kind,name,amount,next_due,frequency) VALUES (?,?,?,?,?,?)", [$U, 'bill', 'Rent', '2000', date('Y-m-d', strtotime('+5 days')), 'monthly']); q("INSERT INTO recurring_items (user_id,kind,name,amount,next_due,frequency) VALUES (?,?,?,?,?,?)", [$U, 'income', 'Pay', '5000', date('Y-m-d', strtotime('+10 days')), 'monthly']); $s = Cash::safe($U); eq($s['safe_c'], 1000000 - 200000 - 50000); eq($s['safe_with_income_c'], 750000 + 500000); });
tc('CASH-02 forecast flags a shortfall on the right date with assumptions listed', function () { $U = mk('Cash2', '1000'); $d = date('Y-m-d', strtotime('+3 days')); q("INSERT INTO recurring_items (user_id,kind,name,amount,next_due,frequency) VALUES (?,?,?,?,?,?)", [$U, 'rent', 'Rent', '5000', $d, 'monthly']); $f = Cash::forecast($U); eq($f['shortfall']['date'], $d); ok(count($f['assumptions']) >= 3); eq(count($f['series']), 31); });
tc('CASH-03 no shortfall when funds cover bills', function () { $U = mk('Cash3', '9000'); q("INSERT INTO recurring_items (user_id,kind,name,amount,next_due,frequency) VALUES (?,?,?,?,?,?)", [$U, 'bill', 'B', '1000', date('Y-m-d', strtotime('+3 days')), 'monthly']); ok(Cash::forecast($U)['shortfall'] === null); });
tc('CASH-04 duplicate bill payment is flagged and blocked unless overridden', function () { $U = mk('Cash4', '5000'); q("INSERT INTO recurring_items (user_id,kind,name,merchant,amount,next_due,frequency) VALUES (?,?,?,?,?,?,?)", [$U, 'subscription', 'Netflix', 'Netflix', '800', date('Y-m-d'), 'monthly']); $id = (int)val('SELECT MAX(id) FROM recurring_items'); Pay::payBill($U, $id, 'b1'); q('UPDATE recurring_items SET next_due=CURDATE() WHERE id=?', [$id]); raises(fn() => Pay::payBill($U, $id, 'b2'), 'duplicate'); ok(val("SELECT COUNT(*) FROM risk_alerts WHERE user_id=? AND alert_type='duplicate_expense'", [$U]) >= 1); Pay::payBill($U, $id, 'b3', true); eq(bal($U), '3400.00'); inv(); });
tc('CASH-05 paying a monthly bill advances next due date by one month', function () { $U = mk('Cash5', '5000'); $d = date('Y-m-d'); q("INSERT INTO recurring_items (user_id,kind,name,amount,next_due,frequency) VALUES (?,?,?,?,?,?)", [$U, 'bill', 'Gas', '100', $d, 'monthly']); $id = (int)val('SELECT MAX(id) FROM recurring_items'); Pay::payBill($U, $id, 'b9'); eq(val('SELECT next_due FROM recurring_items WHERE id=?', [$id]), date('Y-m-d', strtotime($d . ' +1 month'))); });
// ===================== 19. Pockets =====================
tc('POCK-01 pocket deposit/withdraw moves value between wallet and pocket ledger accounts', function () { $U = mk('PK', '1000'); $p = Pockets::create($U, 'Edu', 'education', '5000', null); Pockets::move($U, $p, cents('300'), 'in'); eq(bal($U), '700.00'); eq(val('SELECT balance FROM ledger_accounts WHERE id=(SELECT account_id FROM pockets WHERE id=?)', [$p]), '300.00'); raises(fn() => Pockets::move($U, $p, cents('400'), 'out'), 'Insufficient'); Pockets::move($U, $p, cents('100'), 'out'); eq(bal($U), '800.00'); inv(); });
tc('POCK-02 a user cannot touch another user\'s pocket', function () { $U = mk('PK2', '1000'); $V = mk('PK3', '1000'); $p = Pockets::create($U, 'Mine', 'travel', '500', null); raises(fn() => Pockets::move($V, $p, cents('10'), 'in'), 'not found'); });
// ===================== 20. DB-level guards =====================
tc('DB-01 negative wallet balance is impossible even by direct SQL (CHECK constraint)', function () use ($A) { try { q("UPDATE ledger_accounts SET balance=-1 WHERE code=?", ["W-$A-BDT"]); throw new Exception('DB accepted negative balance'); } catch (PDOException $e) { ok(true); } });
tc('DB-02 unbalanced ledger posting is refused by the posting engine', function () use ($A) { $w = Ledger::wallet($A, 'BDT'); try { tx(function () use ($w) { [$id] = Ledger::newTxn(['type' => 'topup', 'status' => 'completed', 'to_wallet' => $w['id'], 'amount_c' => 100, 'currency' => 'BDT', 'created_by' => 1]); Ledger::post($id, 'post', [[(int)$w['account_id'], 'C', 100, 'BDT']]); }); throw new Exception('unbalanced posting accepted'); } catch (LogicException $e) { ok(true); } });
tc('DB-03 failed posting leaves no orphan transaction (savepoint/rollback)', function () { $S = mk('Orph', '10'); $R = mk('Orph2', '0'); $n = val('SELECT COUNT(*) FROM transactions'); try { send($S, $R, '500'); } catch (AppError $e) {} eq(val('SELECT COUNT(*) FROM transactions'), $n); });
tc('DB-04 SQL injection attempt in recipient field is treated as data', function () use ($A) { raises(fn() => Pay::findUser("x' OR '1'='1", $A), 'not found'); });
tc('LED-01 FINAL: all ledger invariants hold after the entire suite', fn() => inv());
tc('LED-02 every wallet balance equals the sum of its ledger entries', function () { $bad = rows("SELECT w.id FROM wallets w JOIN ledger_accounts a ON a.id=w.account_id WHERE a.balance <> (SELECT COALESCE(SUM(CASE direction WHEN 'C' THEN amount ELSE -amount END),0) FROM ledger_entries WHERE account_id=a.id)"); eq(count($bad), 0); });
$out = []; foreach ($results as [$s, $n, $m]) $out[] = "$s  $n" . ($m ? "  -- $m" : '');
$tot = count($results); $sum = "\nTOTAL $tot  PASSED " . ($tot - $failed) . "  FAILED $failed\n";
echo implode("\n", $out) . $sum; file_put_contents(__DIR__ . '/results.txt', implode("\n", $out) . $sum);
exit($failed ? 1 : 0);
